import{_ as e,o as a,c as s,a3 as i}from"./chunks/framework.BFeCKmyl.js";const p=JSON.parse('{"title":"Apontar documentos com sigilo nível 3 em processos migrados (TJMG)","description":"","frontmatter":{"title":"Apontar documentos com sigilo nível 3 em processos migrados (TJMG)","id":"eproc-sigilo-nivel3-migrados","plataforma":"eproc","tribunal":"TJMG","grupo":"Migração PJe (TJMG)","plano":"free","desde":"1.8.0","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-sigilo-nivel3-migrados.md","filePath":"funcionalidades/eproc-sigilo-nivel3-migrados.md"}'),r={name:"funcionalidades/eproc-sigilo-nivel3-migrados.md"};function l(t,o,n,d,c,m){return a(),s("div",null,o[0]||(o[0]=[i('<h1 id="apontar-documentos-com-sigilo-nivel-3-em-processos-migrados-tjmg" tabindex="-1">Apontar documentos com sigilo nível 3 em processos migrados (TJMG) <a class="header-anchor" href="#apontar-documentos-com-sigilo-nivel-3-em-processos-migrados-tjmg" aria-label="Permalink to &quot;Apontar documentos com sigilo nível 3 em processos migrados (TJMG)&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>A migração do PJe aplica o sigilo &quot;Interno Nível 3&quot; a todo documento que era sigiloso lá. Com esse nível, as partes não veem a peça, e isso costuma passar despercebido. Este recurso aponta esses documentos: uma faixa acima da tabela de eventos lista onde estão, e cada documento ganha uma marca.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc do TJMG</strong>, página do processo, em processos migrados do PJe: faixa acima da tabela de eventos e marca ao lado de cada documento afetado.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo migrado. Se houver documentos importados com sigilo nível 3, aparece a faixa &quot;N documentos com sigilo nível 3 em eventos importados do PJe&quot;, com os eventos clicáveis.</li><li>Clique num evento da faixa para ir até ele.</li><li>Ao lado de cada documento afetado aparece uma marca com o número 3. Clique nela para: <ul><li><strong>Confirmar nível 3 (não avisar mais)</strong>, se o sigilo estiver correto;</li><li>escolher outro nível em <strong>Alterar para:</strong> (nível 0, 1 ou 2): o eploc altera o sigilo em segundo plano, sem abrir a tela, e a marca passa a mostrar o novo nível. Se não conseguir, abre a tela de sigilo do documento para você concluir. Para subir o sigilo (nível 4 ou 5), use a opção abaixo;</li><li><strong>Abrir a tela de sigilo deste documento</strong>, para alterá-lo à mão.</li></ul></li><li>O atalho da faixa abre a alteração de sigilo em bloco (veja <a href="./eproc-sigilo-documentos-lote">Alterar sigilo de vários documentos de uma vez</a>). Ela serve para os demais documentos do processo: o eproc não lista ali os documentos com sigilo nível 3.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Só são verificados os documentos dos eventos importados (anteriores ao evento de migração ou com &quot;ID no PJe&quot;).</li><li>O eproc só permite alterar um a um o sigilo de documentos com nível acima de 1: eles não aparecem na alteração de sigilo em bloco. Para os documentos de nível 3, use a marca de cada documento.</li><li>O nível de sigilo é lido do balão de informações do documento. Documentos sem essa informação não são apontados.</li></ul>',11)]))}const g=e(r,[["render",l]]);export{p as __pageData,g as default};
